import{d as l,N as i,i as a,l as o}from"./chunks/framework.DAESqsOv.js";const f=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍","outline":"deep"},"headers":[],"relativePath":"excel/introduction.md","filePath":"excel/introduction.md","lastUpdated":1778907358000}'),c={name:"excel/introduction.md"};function t(r,e,d,n,s,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="表格" tabindex="-1">表格 <a class="header-anchor" href="#表格" aria-label="Permalink to &quot;表格&quot;">​</a></h1><p><code>@norio-office/office-excel</code> 是一个面向 <code>Vue 3</code> 的在线表格组件，提供工作簿渲染、单元格编辑、工具栏、导入导出、JSON 快照、纯文本读取、基础协同接入和实例 API。</p><p>组件 DOM/CSS 类名前缀统一为 <code>norio-office-excel</code>。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>在业务系统中嵌入在线 Excel / 表格编辑能力</li><li>需要创建、编辑、保存和恢复完整工作簿快照</li><li>需要导入 <code>.xlsx</code> 文件并导出 Excel 文件</li><li>需要获取 JSON 快照或纯文本二维数组</li><li>需要按业务权限控制编辑、导入、导出、sheet 管理、图片、图表和格式化能力</li><li>需要预留多人协同接入，将本地命令交给外部协同服务处理</li></ul><h2 id="产品特点" tabindex="-1">产品特点 <a class="header-anchor" href="#产品特点" aria-label="Permalink to &quot;产品特点&quot;">​</a></h2><ul><li>工作簿模型：<code>v-model</code> 绑定完整 <code>OfficeExcelWorkbookSnapshot</code>。</li><li>表格交互：支持单元格选择、编辑、sheet 切换、复制和只读查看。</li><li>工具栏可配：支持 tabs 模式和 menu 模式，可按 tab 或 command 做白名单/黑名单。</li><li>权限可控：通过 <code>permissions</code> 关闭导入、导出、编辑、sheet 管理、图片、图表和格式化。</li><li>数据可进出：支持导入 Excel、导出 Excel、导出 JSON、下载 JSON、序列化和外部加载。</li><li>协同预留：维护 Yjs 文档镜像，将本地命令转换成外部服务可消费的 command envelope。</li></ul><h2 id="主要能力" tabindex="-1">主要能力 <a class="header-anchor" href="#主要能力" aria-label="Permalink to &quot;主要能力&quot;">​</a></h2><h3 id="表格编辑" tabindex="-1">表格编辑 <a class="header-anchor" href="#表格编辑" aria-label="Permalink to &quot;表格编辑&quot;">​</a></h3><ul><li>初始化工作簿、工作表、行列数量</li><li>单元格选择与编辑</li><li>当前选区变化监听</li><li>当前工作表切换监听</li><li>只读模式与禁用模式</li></ul><h3 id="工具栏与权限" tabindex="-1">工具栏与权限 <a class="header-anchor" href="#工具栏与权限" aria-label="Permalink to &quot;工具栏与权限&quot;">​</a></h3><ul><li><code>tabs</code> 工具栏模式</li><li><code>menu</code> 菜单模式</li><li>tab / command 可见性控制</li><li>编辑、导入、导出、格式化等权限控制</li></ul><h3 id="导入导出" tabindex="-1">导入导出 <a class="header-anchor" href="#导入导出" aria-label="Permalink to &quot;导入导出&quot;">​</a></h3><ul><li>导入 Excel 文件、Blob、ArrayBuffer、Uint8Array</li><li>支持 <code>.xlsx</code> / <code>.xlsm</code> 导入</li><li>导出并下载 <code>.xlsx</code></li><li>导出当前工作簿 JSON</li><li>下载当前工作簿 JSON</li><li>获取当前工作簿或纯文本数据</li></ul><h3 id="背景配置" tabindex="-1">背景配置 <a class="header-anchor" href="#背景配置" aria-label="Permalink to &quot;背景配置&quot;">​</a></h3><ul><li>内置纯色背景和渐变背景</li><li>业务侧可通过 <code>backgroundImages</code> 注入背景图</li><li>背景图 <code>id</code> 会作为 sheet 背景选择的稳定保存值</li><li>工作簿快照中可保存水印、图片、图表等元信息</li></ul><h3 id="协同能力" tabindex="-1">协同能力 <a class="header-anchor" href="#协同能力" aria-label="Permalink to &quot;协同能力&quot;">​</a></h3><ul><li>可选开启协同前端接入层</li><li>维护稳定 ID / Yjs 文档镜像</li><li>将本地操作转换成 command envelope</li><li>通过 provider awareness 展示远程选区</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li>先看 <a href="/office-docs/excel/getting-started">快速开始</a></li><li>需要多人协同接入，再看 <a href="/office-docs/excel/collaboration">协同接入</a></li><li>再看 <a href="/office-docs/excel/api">API 文档</a></li><li>最后看 <a href="/office-docs/excel/demo">Demo 演示</a></li></ol>',20)])])}const m=l(c,[["render",t]]);export{f as __pageData,m as default};
